mapper.select:
SELECT r.transfer_num, r.version, r.from_account_num, f.account_name AS from_account_name, r.to_account_num, t.account_name AS to_account_name, r.transfer_amount, r.transfer_date, r.transfer_memo FROM transfers r JOIN accounts f ON r.from_account_num = f.account_num JOIN accounts t ON r.to_account_num = t.account_num WHERE r.user_num = #{userNum} AND r.use_yn = 'Y'
AND r.transfer_date >= #{startDate} AND r.transfer_date < #{endDate}
ORDER BY r.transfer_date DESC, r.transfer_num ASC

mapper.update:
UPDATE transfers
SET use_yn = 'N', version = version + 1
WHERE transfer_num = #{transferNum}
  AND version = #{version}
  AND use_yn = 'Y'
